{
  "gate_token": "rqdequMfIqjNGypWiXtakw",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined royal city.",
      "visual_description": "A windswept hill at dusk overlooking a shattered skyline of broken spires; Mara crouches with a parchment map weighted by stones, brass compass spinning.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of the road ahead.",
      "visual_description": "A small oil lamp held aloft, its single flame-eye flaring orange, casting long shadows across cracked cobblestones leading toward the city wall.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the castle gates.",
      "visual_description": "A clockwork fox with blue glass eyes peers between rusted iron bars of a colossal gate, key-wind tail ticking, ivy strangling the hinges.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives through a shop window.",
      "visual_description": "A figure in a clear diving helmet steps out of a shattered storefront pane, coat shimmering with reflections of broken streetlamps.",
      "characters": ["glass_diver", "mara_the_cartographguer"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers in a deserted plaza.",
      "visual_description": "Four figures meet beside a toppled fountain choked with old royal banners; moonlight slants between leaning towers.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "They discover the sleeping tax collector slumped in a booth.",
      "visual_description": "A toll booth lit by a sputtering lantern; an official snores upon a fat ledger, stamped papers fluttering off his sleeves in the breeze.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Oracle lamp refuses the cursed tower's invitation.",
      "visual_description": "A black tower leans overhead, its doorway weeping green smoke; the lamp's eye narrows sharply, refusing to step closer.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "guard_note": null,
      "scene_number": 8,
      "caption": "Tin fox slips past an armored patrol unseen.",
      "visual_description": "Polished metal boots tramp through a narrow alley while a tiny clockwork fox flattens itself in a gutter of glittering rainwater.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara charts a hidden route under old royal banners.",
      "visual_description": "An archway draped in faded crimson cloth bearing tarnished gold sigils; Mara sketches a side passage onto her map by lamplight.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a winged beast rattle the rooftops.",
      "visual_description": "A massive shadow with leathery wings sweeps across moonlit tiles; the team ducks behind a chimney as embers swirl down.",
      "characters": ["glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver dives through a stained window.",
      "visual_description": "The rescuer plunges headfirst into a tall cathedral pane, the glass rippling like water, colored shards rising in his wake.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside the keep, a magic door blocks the way.",
      "visual_description": "A circular door of interlocking silver rings spins slowly; runes flare red as the lamp lifts its eye to read them.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Tin fox cracks the lock with a delicate paw.",
      "visual_description": "The clockwork fox inserts its slender tail-key into a rune-slot; gears tick, and the silver rings shudder open with a hiss of pale steam.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive in a mirrored chamber.",
      "visual_description": "A vast hall of cracked mirrors; a chained figure huddles at the center, reflections fracturing into a hundred frightened faces.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector stumbles into the escape, still half-asleep.",
      "visual_description": "Doors burst open as the official sleepwalks through, ledger tucked under one arm, papers trailing, oblivious to falling masonry behind him.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Frightened townsfolk huddle as the team rushes past.",
      "visual_description": "Shadowed figures peek from boarded windows along a narrow lane while Mara waves them back, lamp swinging wildly in her grip.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The team sprints toward the long stone bridge.",
      "visual_description": "A crumbling viaduct stretches over a moonlit chasm; torches bob behind them as the four rescuers race across mossy flagstones.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, the lamp dims with relief.",
      "visual_description": "Dawn breaks over distant hills; the bridge collapses behind them into mist as the team stands silhouetted, the lamp's eye softening to a warm ember.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

